import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static boolean vowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), q = nextInt();
        int[] pre = new int[n + 1];
        for (int i = 0; i < n; i++) {
            String s = next();
            pre[i + 1] = pre[i] + (vowel(s.charAt(0)) && vowel(s.charAt(s.length() - 1)) ? 1 : 0);
        }
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < q; t++) {
            String s = next();
            int dash = s.indexOf('-');
            int l = Integer.parseInt(s.substring(0, dash)), r = Integer.parseInt(s.substring(dash + 1));
            if (t > 0) sb.append('\n');
            sb.append(pre[r] - pre[l - 1]);
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func vowel(c byte) bool {
	return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := int(nextInt()), int(nextInt())
	pre := make([]int, n+1)
	for i := 0; i < n; i++ {
		s := next()
		pre[i+1] = pre[i]
		if vowel(s[0]) && vowel(s[len(s)-1]) {
			pre[i+1]++
		}
	}
	out := make([]byte, 0, 8*q)
	for t := 0; t < q; t++ {
		s := next()
		dash := strings.IndexByte(s, '-')
		l, _ := strconv.Atoi(s[:dash])
		r, _ := strconv.Atoi(s[dash+1:])
		if t > 0 {
			out = append(out, '\n')
		}
		out = strconv.AppendInt(out, int64(pre[r]-pre[l-1]), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
